```jsx
// 客户端：服务端已在 #root 内输出同一 App 的 HTML。
import {hydrateRoot} from 'react-dom/client';
import App from './App.jsx';
const initialData=JSON.parse(document.querySelector('#initial-data').textContent);
hydrateRoot(document.querySelector('#root'), <App data={initialData} />);
```
服务端必须安全序列化 initial-data，避免把用户文本当 script 或 HTML 语法。例子只是客户端入口，真实项目还需路由、构建清单、流式响应和错误处理，优先采用成熟框架。用户专属数据不应进入全局公共缓存。

```jsx
import { useMemo,memo } from 'react';
const Results = memo(function Results({rows}) {
  return <ul>{rows.map(row=><li key={row.id}>{row.title}</li>)}</ul>;
});
export default function Search({items,query}) {
  const rows=useMemo(
    ()=>items.filter(item=>item.title.includes(query)),
    [items,query]
  );
  return <Results rows={rows} />;
}
```
如果 items/query 未变，rows 的引用可以复用，Results 才有机会受益。若父组件每次都创建新的 items，即使内容相同，依赖仍会变化。反过来直接原地修改同一数组又可能使缓存错误地认为没有变化。缓存与不可变数据约定是一组协作条件。

