package main

import (
	"fmt"
	"sync"
)

func main() {
	var wg sync.WaitGroup
	results := make([]int, 3)
	for i := range results {
		wg.Add(1)
		go func(index int) {
			defer wg.Done()
			results[index] = index * index
		}(i)
	}
	wg.Wait()
	fmt.Println(results)
}
```
这里每个 goroutine 写不同元素，主程序在 Wait 返回后读取，不需要为了输出顺序依赖任务完成先后。WaitGroup 负责等待，不会自动传播业务错误、限制任务数量或取消其它任务。Add 的调用安排应避免与等待错误竞争。

