package main

import (
	"context"
	"fmt"
)

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan string, 1)
	go func() {
		<-ctx.Done()
		done <- ctx.Err().Error()
	}()
	cancel()
	fmt.Println(<-done)
}
```
取消会关闭 Done 通道，等待者可以观察它；多个等待者都能收到关闭通知。cancel 应在不用时调用，以释放相关资源，通常创建后立即 defer cancel。对于 WithTimeout，成功提前返回也仍需取消，不能只等待计时器自然结束。

