package main

import (
	"fmt"
	"sync"
)

func main() {
	var mu sync.Mutex
	var wg sync.WaitGroup
	total := 0
	for i := 0; i < 4; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < 100; j++ {
				mu.Lock()
				total++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	fmt.Println(total)
}
```
锁保护的范围应覆盖完整不变量，而不是随意把某一行围起来。持锁期间做慢网络请求会延长等待；多个锁还需一致顺序避免死锁。使用后的 Mutex 不应被随意复制，含锁结构体的方法与传参也要小心。

