labs.solution:
function componentCount(n, edges) {
  const parent = Array.from({ length: n }, (_, i) => i),
    size = Array(n).fill(1);
  let count = n;
  function find(x) {
    while (x !== parent[x]) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }
  for (const [a, b] of edges) {
    let x = find(a),
      y = find(b);
    if (x === y) continue;
    if (size[x] < size[y]) [x, y] = [y, x];
    parent[y] = x;
    size[x] += size[y];
    count--;
  }
  return count;
}

